const { Duplex } = require('stream');

// Creating a custom Duplex stream from scratch
const myDuplex = new Duplex({
  // The Writable side
  write(chunk, encoding, callback) {
    console.log(`[Duplex Received]: ${chunk.toString()}`);
    callback(); // Signals we are ready for the next chunk
  },
  // The Readable side
  read(size) {
    this.push("Hello from Duplex!");
    this.push(null); // Signifies the end of the readable data
  }
});

// Using the Readable side
myDuplex.on('data', (chunk) => {
  console.log(`[Duplex Sent]: ${chunk.toString()}`);
});

// Using the Writable side
myDuplex.write("I am sending data to the duplex!");
myDuplex.end();
